local enums = {
	Attribute = {
		FrameworkReady = "FrameworkReady"
	},
	Data = {
		Loaded = "Loaded",
		NoLoad = "NO LOAD",
	}
}

return enums

local initialValues = {
	-- The name of the datastore used by the Data Store to store the data
	-- that players have collected.

	-- Example of how data can be set up
	--[[
	ExampleDataStore1 = {
		Playtime = 0,
		HalloweenCandies = 0
	},
	ExampleDataStore2 = {
		Event = "HalloweenEvent",
		Banned = true,
		Items = {
			4343758,  -- ColdFyre Armor
			28521575  -- Slime Shield
		},
		Powers = {
			WalkSpeed = 100,
			JumpPower = 2000
		}
	},
	--]]

	isServer = true,

	-- When set to true the ModuleData will no longer track the data that
	-- have been changed. This can be used when testing instead of having 
	-- to manually delete the entries in the DataStore.
	resetOnPlayerRemoving = true,
}

return initialValues

export type PlayerData = { [string]: any }

local CachedData = {}

function CachedData.init()
	CachedData._playerData = {} :: { [Player]: PlayerData }
	CachedData._threadsPendingPlayerDataLoad = {} :: { [Player]: { thread } }
	CachedData._playerDataLoadErrors = {} :: { [Player]: string }
end

--[[
	Cleans up resources used by this player

	Parameters:
	key: The key of the player to clean up resources for
]]
function CachedData.clearCache(player: Player)
	CachedData._playerData[player] = nil
	CachedData._playerDataLoadErrors[player] = nil
	CachedData._threadsPendingPlayerDataLoad[player] = nil
end

return CachedData
